import fs from 'fs';
import path from 'path';
import { fileURLToPath } from 'url';

const __dirname = path.dirname(fileURLToPath(import.meta.url));

const questionsToAppend = {
  ux_writing: [
    {q: "You are a UX writer at a fintech company. The app needs to communicate to users that a feature they rely on is being deprecated in 30 days. How do you write this announcement to minimize churn?", a: `Feature deprecation announcements are high-risk communications because they represent a reduction in value for users who rely on the feature. The copy must be honest about what is changing while giving users clear paths to alternatives that preserve or improve their experience.\n\nThe principles that minimize churn in deprecation communication:\n\nAnnounce early with a specific date. Thirty days is the minimum; sixty is better. Vague timelines ("soon" or "in the coming weeks") create anxiety because users cannot plan. A specific date allows users to adjust on their own schedule.\n\nLead with the alternative, not the loss. "We're introducing a better way to do X" followed by what is being removed is received better than "We're removing X" followed by the alternative. The alternative being genuinely better is the prerequisite for this framing to be credible.\n\nIn-app announcement:\n\nHeadline: [Feature name] is changing on [Date]\n\nBody: We're replacing [Feature name] with [New feature/approach], which gives you [specific improvement]. After [Date], [Feature name] will no longer be available.\n\nHere's what this means for you:\n→ Your existing [data/settings] will automatically move to the new experience\n→ You'll find [equivalent functionality] under [location]\n→ [Any specific thing the user needs to do before the date]\n\nCTA: Try the new experience\nLink: What's changing and why\n\nWhat to avoid: "We're constantly improving our product" (dismissive), "Thank you for your understanding" (patronizing), and any framing that minimizes the change's impact on users who relied on the deprecated feature.`, subcategory: null, difficulty: "Hard", domain: "fintech", tracks: ["UX Writing"], companies: [], roundType: "ux_writing", whatInterviewerTests: "", commonMistakes: []},
    {q: "You are a UX writer at a bank. The bank is introducing mandatory two-factor authentication for all users. Some users will find this inconvenient. How do you write the rollout communication?", a: `Mandatory security changes that add friction are among the most difficult UX writing challenges because the company is asking users to do something they did not choose to do, which they may find annoying, in the name of their own protection.\n\nThe key principles for mandatory security rollout copy:\n\nBe direct about the mandatory nature immediately. Do not bury "this is required" at the bottom of a long explanation. Users who discover something is mandatory after reading a choice-framed introduction feel misled.\n\nExplain the specific threat that makes this necessary. "We've seen a significant increase in account takeover attempts across banking apps in India" is more compelling than "security is our top priority." A specific reason makes the mandate feel necessary rather than arbitrary.\n\nAcknowledge the inconvenience honestly. "We know adding a step to login isn't what anyone wants" is disarming and human. Pretending there is no inconvenience is condescending.\n\nRollout communication:\n\nHeadline: Two-step login is now required for all accounts\n\nBody: Starting [Date], you'll need to verify your identity with a second step every time you log in. This is now mandatory for all accounts.\n\nWhy we're doing this: Account fraud in digital banking has increased significantly this year. Two-step verification prevents unauthorized access even if your password is compromised.\n\nHow it works:\n1. Enter your password as usual\n2. We'll send a 6-digit code to your registered mobile number\n3. Enter the code — takes about 10 seconds\n\nWe know this adds a step. We believe it's the right trade-off to keep your money safe.\n\nCTA: Set up two-step login now\nLink: Why this matters\n\nThe closing sentence that acknowledges the trade-off explicitly is important. It shows the bank has weighed the inconvenience and made a considered decision, not an arbitrary one.`, subcategory: null, difficulty: "Hard", domain: "banking", tracks: ["UX Writing"], companies: [], roundType: "ux_writing", whatInterviewerTests: "", commonMistakes: []},
    {q: "You are a UX writer at an insurance company. You need to write the copy for a feature that shows users how much they have saved by using their insurance versus paying out of pocket. How do you frame this effectively?", a: `A savings summary feature in insurance is an opportunity to demonstrate the value of coverage to users who may feel they are paying premiums without seeing tangible benefit — especially users who have not made claims. The copy must make the abstract value of coverage concrete.\n\nFor users who have made claims:\n\nHeadline: Insurance saved you ₹1,84,000 this year\n\nBody: Here's the difference your coverage made:\n\nHospitalization in March\nTotal bill: ₹2,10,000\nYou paid: ₹26,000 (co-payment + deductible)\nInsurance covered: ₹1,84,000\n\nThis is the most powerful version of the savings summary because the numbers are real and personal.\n\nFor users who have not made claims:\n\nThis is the more challenging copy challenge. Showing someone who paid ₹15,000 in premiums and made zero claims that they "saved nothing" is accurate but not useful. The frame that works: protection value, not transaction value.\n\nHeadline: Your coverage was there when you needed it\nBody: You didn't need to make a claim this year — that's the best outcome. Your ₹15,000 premium gave you ₹10 lakh of coverage for the entire year. That protection was available every day, for anything that could have happened.\n\nThis framing is honest — it does not claim the user saved money — but it reframes insurance from a transaction ("did I get value?") to a protection ("was I covered?"). It is also accurate: the user genuinely did have ₹10 lakh of protection available throughout the year.`, subcategory: null, difficulty: "Medium", domain: "insurance", tracks: ["UX Writing"], companies: [], roundType: "ux_writing", whatInterviewerTests: "", commonMistakes: []},
    {q: "You are a UX writer at a telecom company. Write the copy for a widget that shows real-time network quality at the user's current location. The quality is currently poor.", a: `A real-time network quality widget showing poor quality is a transparency feature that must balance honesty with not alarming users unnecessarily or making them feel the network is unreliable in general.\n\nWidget copy — poor signal state:\n\nWidget headline: Network quality — Fair\n\nSignal indicator: [2 of 5 bars, amber color]\n\nExpanded state (when user taps):\nHeadline: Network quality is lower than usual here\n\nBody: You may experience slower data speeds or call drops in this area right now.\n\nCurrent conditions:\n→ Data speeds: Reduced\n→ Voice calls: May experience interruptions\n→ SMS: Working normally\n\nHelps to know:\n→ Move to an open area or near a window\n→ Connect to WiFi if available\n→ This may improve as you move\n\nLink: Report a network issue\nLink: Check network status in your area\n\nWhat makes this copy effective:\n\n"Fair" rather than "Poor" or "Bad" because it is honest without being alarming. The widget is real-time — network quality changes — and labeling it "Poor" when it might improve in minutes is more alarming than the situation warrants.\n\n"Lower than usual here" attributes the quality issue to the location, not the network in general. This is accurate — network quality varies by location — and prevents the user from generalizing poor quality in one spot to the entire network.\n\nThe "Helps to know" section gives the user actionable steps rather than leaving them with a problem and no path forward.`, subcategory: null, difficulty: "Medium", domain: "telecom", tracks: ["UX Writing"], companies: [], roundType: "ux_writing", whatInterviewerTests: "", commonMistakes: []},
    {q: "You are a content designer at a fintech company. You are designing the copy for a credit score feature. The user's score has just improved by 45 points. How do you celebrate this milestone?", a: `A credit score improvement is a genuine financial achievement worth celebrating, but the celebration must be proportionate, specific about what caused the improvement, and actionable about what comes next.\n\nImprovement notification:\n\nPush notification:\nTitle: Your credit score improved! 🎉\nBody: Up 45 points to 712. See what's working.\n\nIn-app screen after tapping notification:\n\nHeadline: 45 points up — great progress\n\nScore display: 712 [Up from 667]\n[Progress bar showing movement toward next milestone — e.g., 750]\n\nWhat's working:\n→ On-time payments for 6 months in a row ✓\n→ Credit utilization below 30% ✓\n→ No new credit applications in 90 days ✓\n\nWhat this means for you:\n→ You've moved from Fair to Good credit range\n→ You may now qualify for better loan interest rates\n→ Keep this up and you could reach 750 by October\n\nCTA: See what else you can do\n\nThe celebration is specific and earned. "45 points up" is specific — it quantifies the achievement. "What's working" tells the user what behaviors caused the improvement, which reinforces those behaviors. "What this means" translates the abstract score improvement into concrete financial implications. The forward projection "could reach 750 by October" maintains momentum without making a promise.\n\nI avoid over-the-top celebration language. Financial improvements deserve acknowledgment, not a party — the tone should be warm and encouraging without feeling performative.`, subcategory: null, difficulty: "Medium", domain: "fintech", tracks: ["UX Writing"], companies: [], roundType: "ux_writing", whatInterviewerTests: "", commonMistakes: []},
    {q: "You are a UX writer at a banking app. You need to write the copy for a document upload feature where users submit ID proof and address proof for account verification. List all the copy elements needed and write them.", a: `A document upload flow for KYC verification requires copy at every point of the user journey — before, during, and after upload — because document upload is a technically and emotionally sensitive interaction.\n\nCopy elements needed:\n\n1. Introduction screen:\nHeadline: Verify your identity\nBody: We need two documents to complete your account setup. This takes about 5 minutes.\n\nWhat you need:\n→ Identity proof (Aadhaar, PAN, Passport, or Voter ID)\n→ Address proof (Aadhaar, utility bill from last 3 months, or bank statement)\n\nCTA: Start verification\n\n2. Document type selector (for identity proof):\nHeadline: Choose your identity document\n[Option buttons: Aadhaar / PAN Card / Passport / Voter ID]\n\n3. Upload instructions (once document type is selected):\nHeadline: Upload your Aadhaar\nBody: Take a photo or upload from your gallery. Make sure:\n→ All four corners are visible\n→ Text is clear and readable\n→ The document is not expired\n\nCTA: Take photo / Upload from gallery\n\n4. Upload in progress:\n"Uploading your document..."\n\n5. Processing state:\n"Verifying your document — this takes about 30 seconds"\n\n6. Success state:\nHeadline: Identity proof verified ✓\nBody: Now let's verify your address.\nCTA: Continue\n\n7. Failure state:\nHeadline: We couldn't verify this document\nBody: The image may be blurry or the document details are unclear. Please try again with a clearer photo.\nCTA: Try again\nLink: Use a different document\n\n8. Completion:\nHeadline: Verification complete\nBody: Your documents have been verified. Your account is now fully active.\nCTA: Go to my account`, subcategory: null, difficulty: "Medium", domain: "banking", tracks: ["UX Writing"], companies: [], roundType: "ux_writing", whatInterviewerTests: "", commonMistakes: []},
    {q: "You are a UX writer at an insurance company. Write the copy for an in-app feature that helps users understand what their policy does NOT cover. This is information users need but avoid reading.", a: `Exclusions are the most important and most avoided part of any insurance policy. The UX writing challenge is making exclusions accessible and understandable without creating anxiety or making users feel they have been sold something worthless.\n\nDesign principle: Make exclusions feel like useful information, not fine print.\n\nFeature entry point:\nHeadline: What's not covered\nSub-heading: Knowing this helps you plan better\n\nThis framing positions exclusions as useful knowledge rather than bad news.\n\nExclusions display — by category:\n\nPre-existing conditions waiting period\nIllnesses you had before your policy started are covered after [X] years. This protects you going forward — it's not a permanent exclusion.\n[Learn more]\n\nCosmetetic and elective procedures\nTreatments that are not medically necessary — like cosmetic surgery or weight loss programs — are not covered.\n[See full list]\n\nAlcohol and drug-related treatment\nHospitalization directly caused by alcohol or drug use is not covered.\n\nFooter note:\nThis is a summary. Your full policy document has the complete exclusions list, which is the legal reference in case of a claim.\n[View full policy]\n\nWhat makes this effective:\n\nI organize exclusions by category rather than presenting them as a wall of text. Categories make the list scannable and allow users to quickly find what is relevant to their situation.\n\nFor the waiting period exclusion, I add context: "This protects you going forward — it's not a permanent exclusion." This reframe significantly reduces the negative impact of learning about the waiting period.\n\nThe footer note is honest about the summary nature of the in-app display without making the user feel they have been shown misleading information.`, subcategory: null, difficulty: "Hard", domain: "insurance", tracks: ["UX Writing"], companies: [], roundType: "ux_writing", whatInterviewerTests: "", commonMistakes: []},
    {q: "You are a UX writer at a telecom company. The app is introducing a feature that uses AI to predict when a user will run out of data based on their usage patterns. Write the prediction notification copy for three scenarios: 3 days until empty, 1 day until empty, and data just ran out.", a: `Predictive data notifications must be specific, useful, and calibrated in urgency — each scenario requires a different tone that matches the actual urgency level without being either dismissive or alarmist.\n\n3 days until empty — Informational:\n\nPush notification:\nTitle: You'll run out of data in about 3 days\nBody: Based on how you've been using data this month, your 5GB will run out by July 16. Add data now to stay covered.\n\nIn-app card:\nHeadline: Data running low\nBody: At your current usage rate, you'll use your remaining 2.1GB by July 16 — 3 days earlier than your plan resets.\nCTA: Add more data\nLink: Adjust my alerts\n\n1 day until empty — Urgent:\n\nPush notification:\nTitle: Less than 1 day of data left\nBody: You're likely to run out of data by tomorrow. Top up now to avoid slow speeds.\n\nIn-app card:\nHeadline: Data almost gone\nBody: You have about 400MB left. At your current pace, that's less than a day.\nCTA: Top up now — takes 2 minutes\nLink: See my usage\n\nData just ran out — Resolution-focused:\n\nPush notification:\nTitle: You've used all your data\nBody: Your data has run out. You're now on reduced speeds. Add data to get back to full speed.\n\nIn-app screen:\nHeadline: Your data is finished\nBody: You've used your full 5GB for this month. Your connection is still active at reduced speeds.\n\nTo get back to full speed:\n→ Add a data pack [CTA: Add data]\n→ Or wait until your plan resets on [Date]\n\nThe three tiers show deliberate escalation: informational framing at 3 days, urgency framing at 1 day, and resolution framing when data is gone. The resolution state is notably non-panicked because the situation, while inconvenient, is not an emergency.`, subcategory: null, difficulty: "Medium", domain: "telecom", tracks: ["UX Writing"], companies: [], roundType: "ux_writing", whatInterviewerTests: "", commonMistakes: []},
  ],
  technical_docs: [
    {q: "You are a technical writer at a fintech company. How do you write effective code examples in API documentation?", a: `Code examples are the most important element of API documentation because developers learn primarily through working examples rather than through descriptive text. A poorly written code example can block an entire integration; a well-written one can enable a developer to integrate in hours rather than days.\n\nPrinciples for effective code examples:\n\nEvery example must be complete and runnable. A partial example that shows only the interesting part of the code while omitting the necessary setup — authentication, error handling, imports — is worse than no example because it gives developers a false starting point. If the complete example is long, show the complete version first and annotate the parts.\n\nShow the real-world use case, not just the syntax. An example that calls an endpoint with fake placeholder values like YOUR_API_KEY and ACCOUNT_ID_HERE gives developers the syntax. An example that shows how to initiate a payment from account A to account B with a specific reference ID demonstrates how the API is actually used. The second is significantly more useful.\n\nInclude the response. Showing only the request is half the story. Show the successful response alongside the request, and show the most common error response with an explanation of how to handle it.\n\nAnnotate with comments. Brief inline comments that explain why the code does something — not what it does, which is obvious — help developers understand the design decisions behind the example. "// Using idempotency key to safely retry failed requests" is a useful comment. "// Send the POST request" is not.\n\nProvide multiple language examples for the most important use cases. If your developer audience uses Python, JavaScript, Java, and PHP, provide examples in all four for the key endpoints. Developers are significantly more likely to use documentation in their own language.\n\nTest every example. Before publishing, verify that each code example actually works against the API. Broken examples are more damaging than no examples.`, subcategory: null, difficulty: "Medium", domain: "fintech", tracks: ["Technical Docs"], companies: [], roundType: "technical_docs", whatInterviewerTests: "", commonMistakes: []},
    {q: "You are a technical writer at a bank. You need to write the documentation for a new mobile banking app's accessibility features. What does this documentation need to cover?", a: `Accessibility feature documentation for a mobile banking app serves two distinct audiences: users with disabilities who want to know what accommodations are available and how to use them, and developers or IT administrators who need to understand the technical accessibility implementation.\n\nFor users with disabilities — Help center article:\n\nThis documentation should be written in plain language, structured by disability type or accommodation need rather than by technical feature:\n\nVision accessibility:\n→ Screen reader support: The app works with VoiceOver on iOS and TalkBack on Android. Every button, input field, and image has a descriptive label that your screen reader will announce.\n→ Text size: Go to Settings > Accessibility > Text Size to increase text throughout the app.\n→ High contrast: Matches your device's high contrast settings automatically.\n→ Large touch targets: All interactive elements are at least 44x44 pixels.\n\nHearing accessibility:\n→ No audio-only information: All audio alerts also appear as visual notifications or text.\n→ Closed captions: Available on all video content in the app.\n\nMotor accessibility:\n→ Full keyboard navigation support on iPad and Android tablets.\n→ Switch access: Compatible with iOS Switch Control and Android Switch Access.\n→ Biometric login: Reduces the need for typing credentials.\n\nCognitive accessibility:\n→ Simple language throughout the app.\n→ No time-limited interactions except where required by security.\n→ Confirmation screens for all irreversible actions.\n\nFeedback:\n"If you encounter any accessibility barrier in our app, we want to know. Contact our accessibility team at [email]."`, subcategory: null, difficulty: "Medium", domain: "banking", tracks: ["Technical Docs"], companies: [], roundType: "technical_docs", whatInterviewerTests: "", commonMistakes: []},
    {q: "You are a technical writer at an insurance company. You need to document a new claims API for hospitals that will allow cashless treatment authorization. What is unique about writing healthcare API documentation?", a: `Healthcare API documentation for cashless insurance claims has characteristics that distinguish it from standard fintech or SaaS API documentation, driven by the clinical context, the regulatory environment, and the high stakes of errors.\n\nUnique characteristics:\n\nClinical data terminology: Healthcare APIs use standardized medical terminologies — ICD-10 diagnosis codes, CPT procedure codes, SNOMED clinical terms — that require explanation for non-clinical developers. The documentation must either define these terms or reference the authoritative sources where they can be looked up. A developer implementing the API may be technically skilled but medically inexperienced.\n\nTransaction timing criticality: In cashless insurance authorization, a delayed API response directly affects patient care. A pre-authorization request that times out means the hospital cannot confirm cashless treatment and the patient may need to pay upfront and claim later. The documentation must clearly specify the API's SLA for response times and what the hospital system should do on timeout — retry, fallback to manual authorization, or prompt the patient.\n\nRegulatory compliance documentation: Insurance cashless APIs in India operate under IRDAI regulations that specify what pre-authorization must include, what information must be retained, and what the timeline requirements are. The API documentation must reference these requirements and explain how the API's design enables compliance, not just describe the API mechanics.\n\nError severity differentiation: In a hospital system processing real patient care, not all API errors are equal. An error in recording the patient's room type is minor. An error in the authorized procedure codes could result in a patient receiving treatment that is not covered. The documentation must distinguish between minor and critical error conditions and specify the appropriate response to each.\n\nTest data requirements: Testing healthcare APIs requires medically realistic synthetic data. Generic test data with placeholder names and arbitrary ICD codes may pass technical validation while missing real-world edge cases. The documentation should provide test cases that cover medically realistic scenarios including edge cases like split admissions, same-day procedures, and pre-authorization for chronic conditions.`, subcategory: null, difficulty: "Hard", domain: "insurance", tracks: ["Technical Docs"], companies: [], roundType: "technical_docs", whatInterviewerTests: "", commonMistakes: []},
    {q: "You are a technical writer at a telecom company. Explain how you would document a complex troubleshooting decision tree for a customer service team.", a: `A troubleshooting decision tree for a customer service team is a structured document that guides agents through diagnosis and resolution in a specific, reproducible sequence. Its design must account for the conditions in which it is used: time pressure, variable agent experience levels, and customers who may be frustrated or distressed.\n\nDesign principles:\n\nStart from the symptom the customer describes, not from a technical categorization. Customers say "my internet is not working" — the decision tree should start at "customer reports no internet connection" rather than at "Layer 3 connectivity failure." The agent must be able to enter the tree using exactly what the customer told them.\n\nBranch based on what the agent can verify in the moment. Each branch point should be answerable from information the agent has available: what the customer says, what they can see in the account management system, and what the customer can observe on their device. Branches that require information the agent cannot obtain create dead ends.\n\nLimit branch depth. A decision tree that goes more than four or five levels deep without reaching a resolution or escalation is too complex for real-time use. Deep trees should be restructured into multiple shallower trees for different symptom categories.\n\nEnd every branch at an action, not a question. Every path through the tree ends at: resolve the customer's issue with this specific action, escalate to the next tier with this specific context, or collect this information and transfer to the relevant team. Dead ends — branches that end at "check further" — are not resolutions.\n\nFormat:\n\nFor agent-facing use, I prefer a visual flowchart format for trees with up to fifteen to twenty nodes, and a structured numbered list format for more complex trees where the visual format becomes cluttered. For digital use, a hyperlinked document that allows agents to click to the next relevant step is more usable than a static diagram that requires scanning.`, subcategory: null, difficulty: "Medium", domain: "telecom", tracks: ["Technical Docs"], companies: [], roundType: "technical_docs", whatInterviewerTests: "", commonMistakes: []},
    {q: "You are a technical writer at a SaaS company. You need to write documentation for a feature that uses machine learning to make predictions. How do you document the uncertainty inherent in ML predictions?", a: `Machine learning predictions are probabilistic, not deterministic. Documenting them accurately requires explaining the uncertainty without either overstating the confidence in predictions or undermining user trust in a useful feature.\n\nThe core documentation challenge:\n\nUsers who do not understand probabilistic prediction tend to interpret ML outputs as facts. "This transaction is flagged as fraudulent" is interpreted as certainty even if the model is 75% confident. Documentation must set accurate expectations about what the prediction means and what confidence level underlies it.\n\nHow to document ML prediction features:\n\nExplain what the model predicts and on what basis: "The risk score is calculated based on the transaction amount, time of day, merchant category, and your historical spending patterns for this category. It does not have access to your personal financial information beyond what is visible in your account activity."\n\nExplain confidence levels in user terms: Avoid technical language like "posterior probability." Use accessible language: "A score above 80 means we're fairly confident this transaction is unusual for you. A score between 50 and 80 means we've detected something worth your attention but we're less certain."\n\nDocument the known limitations explicitly: "The model is trained on historical transaction patterns. It may be less accurate for transactions in categories you rarely use, or for transactions in countries you have not visited before."\n\nDocument what to do when the prediction is wrong: "If we flag a transaction you made yourself, dismiss the alert in the app and the model will learn from your feedback over time." This tells users that errors are expected and manageable, which significantly reduces frustration when errors occur.\n\nFor technical documentation: include the model's precision, recall, and false positive rate so technical users can evaluate the model's performance characteristics. Note the date these metrics were measured, as they will change as the model is updated.`, subcategory: null, difficulty: "Hard", domain: "fintech", tracks: ["Technical Docs"], companies: [], roundType: "technical_docs", whatInterviewerTests: "", commonMistakes: []},
    {q: "You are a technical writer at a bank. You need to write a post-implementation review document for a major core banking system upgrade. What does this document contain?", a: `A post-implementation review document for a core banking system upgrade is both an evaluation of what happened and a learning resource for future projects. It must be honest about what went wrong as well as what went right, and specific enough to be useful rather than generic.\n\nDocument sections:\n\nExecutive summary: A one-page summary of the upgrade outcome — was it successful, what was the final cost and timeline versus plan, and what are the three most important findings. This section is for senior leadership who will not read the full document.\n\nProject overview: What was upgraded, why, and what the original scope, timeline, and budget were. This section is the baseline against which the rest of the document measures actual performance.\n\nDelivery performance: Actual versus planned timeline with specific milestone dates. Actual versus planned budget with cost category breakdown. Scope changes that occurred during the project with their rationale and impact. This is factual, not evaluative — the evaluation comes later.\n\nTechnical outcomes: System performance post-upgrade against defined success criteria. Defects discovered after go-live — their severity, how they were discovered, and how they were resolved. Data migration accuracy — was all data migrated correctly and are there any known data issues outstanding?\n\nOperational impact: Downtime during the cutover — planned versus actual. Staff productivity impact in the first month. Support contact volume changes. Customer-facing impact during the transition period.\n\nWhat went well: Specific things that worked better than expected, with attribution to the specific decisions or actions that contributed to them. Generic "the team worked hard" is not useful. "Pre-migration data quality remediation prevented an estimated 3,000 data errors post-go-live" is useful.\n\nWhat could have been done better: Specific things that did not work as expected, with analysis of the root cause and a specific recommendation for future projects.\n\nRecommendations: Three to five specific, actionable recommendations for the next major system upgrade project.`, subcategory: null, difficulty: "Medium", domain: "banking", tracks: ["Technical Docs"], companies: [], roundType: "technical_docs", whatInterviewerTests: "", commonMistakes: []},
    {q: "You are a technical writer at an insurance company. What is the difference between a process document, a procedure document, and a work instruction, and when do you use each?", a: `Process documents, procedure documents, and work instructions represent three levels of operational documentation, each serving a different level of detail and a different audience within an organization.\n\nProcess document:\n\nA process document describes what happens at a high level — the sequence of activities that transform an input into an output, who is responsible for each activity at a role level, and how the process connects to other processes. It answers "what happens?" not "how do you do it?"\n\nFor an insurance company, a Claims Processing Process document would show: notification received → FNOL logged → documents requested → documents verified → liability assessed → settlement calculated → payment authorized → payment made. It shows the flow and the handoffs between roles without specifying exactly how each step is performed.\n\nAudience: Managers, process owners, auditors, and new employees who need to understand the big picture.\n\nProcedure document:\n\nA procedure document describes how a specific activity in the process is performed — the sequence of steps required to complete one activity from start to finish. It answers "how do you do it?"\n\nFor the claims process, a Claims FNOL Logging Procedure would describe exactly how to record a first notice of loss in the claims management system: what fields to complete, what information to gather from the claimant, what documents to request, and what happens if information is incomplete.\n\nAudience: Staff members who perform the activity.\n\nWork instruction:\n\nA work instruction is the most granular level — a step-by-step description of a single task, often with screenshots or illustrations, for a specific tool or system. It answers "what exactly do I type/click/enter?"\n\nFor the FNOL logging procedure, a work instruction would show screen by screen how to enter a claim in the specific claims management system version currently in use.\n\nAudience: New staff, staff returning from leave, or anyone performing the task for the first time.`, subcategory: null, difficulty: "Easy", domain: "insurance", tracks: ["Technical Docs"], companies: [], roundType: "technical_docs", whatInterviewerTests: "", commonMistakes: []},
  ],
  ai_content: [
    {q: "You are an AI content designer at a fintech company. The company wants to use AI to personalize help center content based on the user's account activity. What are the opportunities and risks?", a: `AI-personalized help center content represents a significant usability improvement opportunity but introduces risks that must be managed carefully in a regulated financial services context.\n\nOpportunities:\n\nRelevance improvement: A user who has just made their first international transfer should see help content about international transfers prominently, not generic getting-started content. AI personalization that surfaces contextually relevant content based on recent account activity reduces search time and increases self-service success rates.\n\nProactive support: AI can identify when account activity patterns suggest a user might have a question before they search for it. A user whose first EMI payment just debited might benefit from seeing "Understanding your EMI schedule" proactively rather than discovering confusion only after contacting support.\n\nJourney-stage adaptation: New users need onboarding content; experienced users need feature discovery and advanced help. Personalization that adapts the help center experience to the user's account maturity serves each stage more effectively.\n\nRisks:\n\nPrivacy perception: Users who see help content that clearly references their specific transactions may feel their account activity is being surveilled even when the personalization is clearly in their interest. The personalization logic must be transparent and the user should be able to understand and control it.\n\nFilter bubble effect: Personalization that shows users only content relevant to their past activity may prevent them from discovering features and capabilities they do not yet know exist. The help center should balance personalization with discoverability of new content.\n\nPersonalization errors: An AI that incorrectly infers the user's situation and surfaces irrelevant or incorrect content may reduce trust more than a generic but accurate help center would. The personalization system needs quality controls.\n\nRegulatory considerations: In India, using customer account data to personalize product experiences has DPDP Act implications. The data use must be disclosed and the user must have consented to this type of data use.`, subcategory: null, difficulty: "Hard", domain: "fintech", tracks: ["AI Content"], companies: [], roundType: "ai_content", whatInterviewerTests: "", commonMistakes: []},
    {q: "You are an AI content engineer at a bank. How do you maintain quality and consistency in an AI assistant's responses over time as the knowledge base grows and the product evolves?", a: `Maintaining quality and consistency in a production AI assistant is an ongoing operations challenge, not a one-time launch task. Without deliberate maintenance, AI assistant quality degrades over time as the knowledge base grows, the product changes, and new edge cases emerge that the original design did not anticipate.\n\nQuality maintenance mechanisms:\n\nRegular sampling and evaluation: I establish a weekly sampling process where a defined set of conversations is reviewed against quality criteria — accuracy, tone, helpfulness, safety. The sample should be structured to cover the most common query types and the highest-risk scenarios (billing disputes, fraud reports, complaint handling). Trends in quality scores over time reveal degradation before it becomes a widespread problem.\n\nKnowledge base currency tracking: Each article in the knowledge base should have a review date and an owner. I implement an automated system that flags articles that have not been reviewed within their defined review period and surfaces them to the owner. A growing knowledge base where old articles are never reviewed is a knowledge base where the AI's responses progressively degrade.\n\nNew content integration testing: Before new knowledge base content is added to production, I test how the AI uses it by running a set of relevant queries and reviewing the responses. New content that causes the AI to produce inconsistent or incorrect responses in adjacent topic areas is revised before deployment.\n\nConversation failure analysis: Conversations that ended with human escalation after AI interaction are analyzed to understand what the AI failed to do that caused the escalation. This analysis feeds directly into system prompt improvements and knowledge base updates.\n\nVersion control for prompts: System prompt changes are version-controlled and tested before deployment. The previous version is retained so that a problematic change can be rolled back quickly.\n\nUser feedback integration: Thumbs-down ratings and explicit feedback from users are reviewed weekly and the most common negative feedback themes are addressed in the next prompt or knowledge base update cycle.`, subcategory: null, difficulty: "Hard", domain: "banking", tracks: ["AI Content"], companies: [], roundType: "ai_content", whatInterviewerTests: "", commonMistakes: []},
    {q: "You are an AI content designer at an insurance company. The company wants to use AI to generate personalized policy summaries for new customers. What are the content design requirements?", a: `AI-generated personalized policy summaries represent a high-value application in insurance because standard policy documents are notoriously difficult for customers to understand, and a personalized summary that speaks to the specific customer's coverage can significantly improve comprehension and reduce complaints about coverage surprises.\n\nContent design requirements:\n\nFactual accuracy from structured data only: The AI must generate summaries based strictly on the customer's actual policy data — sum insured, waiting periods, exclusions, network hospitals in their area, premium breakdown. It must not infer or estimate any policy term. Every factual statement in the summary must be traceable to a verified data source.\n\nPersonalization that is genuinely personal: A summary that says "Your policy" and then shows the same standard terms as every other policy is not personalized — it is a form letter. Genuine personalization means the summary references the customer's specific sum insured amount, their specific plan's network hospitals in their city, the specific waiting periods that apply to conditions they have disclosed, and the specific premium they are paying.\n\nPlain language requirement: Policy documents use legal language; the AI-generated summary must use plain language. Every insurance term must be translated — "sum insured" explained as "the maximum we'll pay for all claims in a year," "co-payment" explained as "the portion of each hospital bill you pay yourself."\n\nMandatory disclosures: Certain regulatory disclosures required by IRDAI must appear in the summary regardless of the AI's personalization choices. The content design must include a list of mandatory elements that the AI is required to include in every generated summary.\n\nHuman review for edge cases: Summaries generated for customers with complex policies — multiple riders, exclusions based on disclosed pre-existing conditions, special terms — should be flagged for human review before delivery rather than auto-delivered.`, subcategory: null, difficulty: "Hard", domain: "insurance", tracks: ["AI Content"], companies: [], roundType: "ai_content", whatInterviewerTests: "", commonMistakes: []},
    {q: "You are an AI content engineer at a telecom company. How do you handle multilingual requirements in an AI customer service assistant for an Indian context?", a: `Multilingual AI for Indian telecom customer service is a complex content engineering challenge because India's linguistic diversity is not just a translation problem — it involves code-switching, dialect variation, script differences, and varying levels of formality across languages that a simple translation approach cannot address.\n\nThe multilingual reality in Indian telecom customer service:\n\nMost customer interactions do not happen in a single language. Indian customers commonly mix Hindi and English (Hinglish), Tamil and English, or regional languages with Hindi. An AI that can only handle pure language inputs will mishandle the majority of real conversations.\n\nApproach:\n\nLanguage detection at the conversation level, not the message level: Individual messages often contain multiple languages. The system should identify the user's primary language from the overall conversation pattern rather than attempting to classify each individual message.\n\nCode-switching support: The AI should be able to understand queries that mix languages and respond in the user's dominant language. A user who asks "Mera plan ka data kab reset hoga?" (When does my plan's data reset?) should receive a response in Hindi, not a message asking them to use a single language.\n\nSeparate knowledge bases by language, not just translations: A translated knowledge base often produces unnatural responses because the structure of information differs by language. A Hindi knowledge base should be written natively in Hindi, not translated from English, so that the AI's responses use natural Hindi phrasing rather than translated constructions.\n\nRegional language prioritization based on circle: A telecom operating in Tamil Nadu should prioritize Tamil language support in its customer service AI for that circle. Language availability should be configurable by service area.\n\nFallback to English with acknowledgment: When the AI is not confident in its ability to handle a query in the customer's language, it should acknowledge this in the customer's language and offer to continue in English, rather than giving a low-quality response in the regional language.`, subcategory: null, difficulty: "Hard", domain: "telecom", tracks: ["AI Content"], companies: [], roundType: "ai_content", whatInterviewerTests: "", commonMistakes: []},
    {q: "You are an AI content designer at a fintech company. What is the difference between a chatbot and a conversational AI, and why does this distinction matter for content design?", a: `The distinction between a chatbot and conversational AI matters for content design because the two systems have fundamentally different capabilities that determine what content approach is appropriate for each.\n\nA chatbot is a rule-based system that follows predefined conversation flows. It matches user inputs to predefined patterns and responds with predefined responses or guides users through scripted decision trees. A chatbot is excellent at handling narrow, well-defined use cases where the conversation paths can be comprehensively mapped in advance.\n\nConversational AI uses natural language understanding and generation to handle open-ended conversations. It can understand intent from varied phrasings, maintain context across multiple turns, and generate contextually appropriate responses rather than selecting from predefined options.\n\nWhy this matters for content design:\n\nFor a chatbot, the content designer creates the conversation scripts — the predefined responses, the button labels, the quick reply options, and the decision tree logic. The quality of the chatbot experience is entirely determined by the quality of these scripts. A chatbot that has not been scripted for a specific scenario cannot handle it — it will either give an inappropriate response or fail entirely.\n\nFor conversational AI, the content designer creates the system prompt, the knowledge base, the evaluation criteria, and the guardrails. The AI can handle scenarios that were not explicitly scripted, which is a significant advantage. But this generativity also means the AI can produce responses that were not anticipated, including incorrect or inappropriate ones — which is why the content design work focuses on constraints and quality assurance rather than scripting every possible response.\n\nIn practice, most enterprise customer service deployments use hybrid approaches: conversational AI for open-ended queries, with chatbot-style scripted flows for high-stakes structured processes like payments, identity verification, and account changes where the exact conversation path matters for compliance and accuracy.`, subcategory: null, difficulty: "Medium", domain: "fintech", tracks: ["AI Content"], companies: [], roundType: "ai_content", whatInterviewerTests: "", commonMistakes: []},
    {q: "You are an AI content engineer at a bank. The bank's AI assistant has started producing responses that work well in isolation but create inconsistency when viewed across a multi-turn conversation. How do you diagnose and fix this?", a: `Multi-turn conversation inconsistency in an AI assistant — where the AI contradicts itself or gives information in turn 5 that conflicts with what it said in turn 2 — is a context management problem that originates in how the conversation history is handled.\n\nDiagnosis:\n\nI analyze a sample of inconsistent conversations to identify the pattern. Common causes:\n\nContext window overflow: In long conversations, early turns are pushed out of the context window. The AI "forgets" what it said earlier because those turns are no longer in the active context. If the AI told the user their savings interest rate was 4% in turn 3 and then quotes 4.5% in turn 12, the earlier information may have been lost from the context.\n\nContradictory knowledge base content: The AI retrieves different documents for different turns of the conversation, and those documents contain slightly inconsistent information. A product terms page that says "4% interest" and a FAQ that says "up to 4.5% interest" will produce inconsistent AI responses if different documents are retrieved at different turns.\n\nNo conversation state tracking: The AI treats each turn as a fresh retrieval without tracking what commitments or information it has already provided in the conversation.\n\nFixes:\n\nFor context window overflow: Implement a conversation summarization mechanism that condenses earlier turns into a structured summary that is included at the start of the context. The summary preserves key information — user's account type, issues discussed, information provided — without consuming full context for every earlier turn.\n\nFor contradictory knowledge base content: Audit the knowledge base for the specific topics that are producing inconsistencies and establish single canonical answers that replace the conflicting versions.\n\nFor conversation state tracking: Add explicit state tracking to the system prompt: "Maintain consistency with information you have already provided in this conversation. If you are uncertain about something you said earlier, acknowledge the uncertainty rather than giving a different answer."`, subcategory: null, difficulty: "Hard", domain: "banking", tracks: ["AI Content"], companies: [], roundType: "ai_content", whatInterviewerTests: "", commonMistakes: []},
    {q: "You are an AI content designer at an insurance company. How do you measure the ROI of an AI assistant implementation and what content metrics matter most?", a: `Measuring the ROI of an AI assistant implementation requires connecting content performance metrics to business outcomes. Without this connection, content teams can demonstrate activity (conversations handled, queries answered) without demonstrating value (cost saved, customers retained).\n\nBusiness outcome metrics:\n\nSupport cost reduction: The primary financial benefit of most AI assistants is deflecting conversations from human agents, who cost significantly more per interaction. ROI is measured as: (number of conversations fully resolved by AI) × (cost per human agent interaction) − (cost of AI implementation and maintenance). For a bank or insurance company with high inbound support volume, even a 20% deflection rate can produce significant savings.\n\nFirst contact resolution rate: Of the conversations the AI handles, what percentage are resolved without human escalation? This is a quality metric that directly affects customer satisfaction and support costs.\n\nCustomer satisfaction: CSAT scores for AI-handled conversations versus human-handled conversations. A well-designed AI assistant should approach but typically not exceed human CSAT scores. Significant gaps indicate content quality problems.\n\nContent-specific metrics that matter most:\n\nZero-result rate: The percentage of queries where the AI has no relevant knowledge base content to retrieve. This directly measures knowledge base coverage.\n\nLow-confidence escalation rate: The percentage of queries where the AI's retrieval confidence is below a defined threshold and it escalates to a human. An improvement in knowledge base quality reduces this rate.\n\nPost-AI human contact rate: The percentage of users who interacted with the AI and then contacted a human agent in the next hour. This is the strongest signal that the AI failed to resolve the user's query — they went to a human immediately after the AI interaction.\n\nKnowledge base freshness score: What percentage of knowledge base content has been reviewed within its defined review period. Aging knowledge base content predicts future accuracy degradation before it manifests in conversation quality metrics.`, subcategory: null, difficulty: "Hard", domain: "insurance", tracks: ["AI Content"], companies: [], roundType: "ai_content", whatInterviewerTests: "", commonMistakes: []},
  ],
  content_strategy: [
    {q: "You are a content strategist at a fintech company. How do you prioritize which documentation gaps to fill first when you have limited resources?", a: `Prioritizing documentation gaps with limited resources requires a framework that translates the size of each gap into a business impact estimate, allowing the team to direct effort toward the highest-value documentation rather than the most visible or the most requested.\n\nThe framework I use has four factors:\n\nVolume of users affected: How many users encounter this gap regularly? A gap in the most common user flow affects more users than a gap in a rarely-used feature. I use search data, support ticket categories, and product analytics to estimate the number of users who need information that is currently missing.\n\nSeverity of the gap: What happens when a user encounters this gap? A gap that causes users to contact support has a measurable cost. A gap that causes users to make errors with their account has a higher cost. A gap that causes users to churn has the highest cost. I estimate the business impact per affected user.\n\nSelf-service potential: Would documentation actually solve this problem, or is the user's need better served by a product change, a proactive notification, or a human interaction? Some gaps cannot be closed with documentation because the underlying issue is product complexity, not missing explanation. I identify and deprioritize these.\n\nEffort to close: How much time does each documentation project require? A high-impact but low-effort documentation project (a single article that answers a common question) should be completed before a high-impact, high-effort project (a comprehensive guide for a complex feature).\n\nWith these four factors assessed for each documented gap, I rank gaps by the ratio of impact to effort and build the documentation roadmap from highest to lowest ratio. I share this framework and ranking with stakeholders so that documentation priority decisions are transparent and evidence-based rather than based on which team asked most loudly.`, subcategory: null, difficulty: "Medium", domain: "fintech", tracks: ["Content Strategy"], companies: [], roundType: "content_strategy", whatInterviewerTests: "", commonMistakes: []},
    {q: "You are a documentation manager at a bank. How do you build a business case for investing in documentation tooling that will cost ₹15 lakhs annually?", a: `A ₹15 lakh annual investment in documentation tooling requires a business case that quantifies the benefit in terms the approving leader cares about: return on investment, productivity gain, risk reduction, and competitive positioning.\n\nCost side:\n\nThe cost is ₹15 lakhs annually in licensing plus one-time implementation costs for migration and training. The total first-year cost is typically higher than subsequent years — I model all three years to show the steady-state cost.\n\nBenefit side — productivity gains:\n\nI calculate the documentation team's current time lost to tooling limitations. If the current tool requires manual formatting that takes an average of 30 minutes per article, and the team publishes 20 articles per month, that is 10 hours per month of avoidable overhead. At a loaded cost of ₹600 per hour, that is ₹72,000 per year in avoidable labor. If the new tool eliminates this overhead and the team has five writers, the saving is ₹3.6 lakh per year.\n\nBenefit side — content quality improvements:\n\nIf the new tooling enables structured authoring, single-sourcing, and automated consistency checking, I estimate the reduction in content errors and the associated reduction in support contacts. A 5% reduction in documentation-related support contacts at a bank with high support volume represents measurable cost savings.\n\nBenefit side — compliance risk reduction:\n\nBetter tooling with workflow management reduces the risk of publishing documentation that has not been through the required compliance review. A single compliance finding related to documentation in a banking context can result in costs far exceeding ₹15 lakhs. I quantify the risk reduction even if I cannot assign a precise probability.\n\nPayback period:\n\nWith the benefits quantified, I calculate the payback period. A case that pays back in 18-24 months is realistic for documentation tooling investment.`, subcategory: null, difficulty: "Hard", domain: "banking", tracks: ["Content Strategy"], companies: [], roundType: "content_strategy", whatInterviewerTests: "", commonMistakes: []},
    {q: "You are a content strategist at an insurance company. How do you design content that converts insurance prospects who are in the consideration stage?", a: `Content for insurance prospects in the consideration stage must bridge the gap between awareness (knowing the company exists) and decision (buying a policy). Consideration-stage prospects are actively comparing options, have identified their need, and are evaluating whether this company's product meets that need.\n\nWhat consideration-stage prospects need:\n\nComparison clarity: Prospects are comparing products, often across multiple companies. Content that makes comparison easy — by presenting coverage, premiums, exclusions, and network hospitals in a standardized, scannable format — serves the prospect's active research goal and positions the company as transparent rather than evasive.\n\nProof of claims experience: The insurance purchase decision is fundamentally about trust that the company will pay when needed. Consideration-stage content must address this with concrete evidence: claims settlement ratio, time to settlement statistics, customer testimonials specifically about claims experience (not general satisfaction), and a transparent explanation of the claims process.\n\nAnswers to the questions that cause hesitation: Research on insurance consideration behavior identifies common hesitation questions: Will pre-existing conditions be covered? What happens if I need to go to a non-network hospital in an emergency? What if I cannot afford the premium one month? Content that directly and honestly answers these questions before the prospect asks them removes friction from the decision.\n\nPersonalization hooks: Different prospect segments have different consideration priorities. A young professional considering health insurance primarily cares about outpatient coverage and mental health coverage. A family buyer cares about pediatric coverage and network hospital proximity. Content that allows self-segmentation — "choosing health insurance for yourself versus your family" — creates a personalized consideration experience without requiring personalization technology.\n\nClear next step: Every consideration-stage content piece should end with a specific next step that is lower commitment than purchasing: get a quote, speak with an advisor, or compare plans. The prospect who is in consideration is not ready to buy — they are ready for a lower-stakes next action.`, subcategory: null, difficulty: "Hard", domain: "insurance", tracks: ["Content Strategy"], companies: [], roundType: "content_strategy", whatInterviewerTests: "", commonMistakes: []},
    {q: "You are a content strategist at a telecom company. How do you create a content strategy for a product that is transitioning from a legacy system to a new platform, with both systems running simultaneously?", a: `A dual-system transition period — where legacy and new platforms run simultaneously — is one of the most complex documentation scenarios because users on different systems need different instructions, support staff need to handle both, and the documentation must not create confusion between the two.\n\nContent strategy for a dual-system transition:\n\nUser segmentation as the organizing principle:\n\nThe documentation structure must first answer "which system are you on?" before providing any procedural guidance. Users who do not know which system they are on should be directed to a system identification guide before any other content.\n\nSeparate documentation trees, not a combined one:\n\nThe instinct to maintain one documentation set for both systems — distinguishing with tabs or callouts like "if you're on the old system, do X; if you're on the new system, do Y" — produces documentation that is confusing for both audiences. I maintain two separate documentation trees that share a common entry point but diverge completely after system identification.\n\nMigration documentation as a third category:\n\nBeyond legacy documentation and new platform documentation, a third category — migration content — covers the transition itself: what migrates automatically, what users need to do to migrate their settings or data, what happens to transactions in progress during migration, and what to do if the migration fails.\n\nTimestamped deprecation of legacy content:\n\nAs users migrate to the new platform, legacy documentation becomes increasingly irrelevant. I add clear deprecation notices to legacy documentation: "This documentation applies to the old platform. If you have migrated to the new platform, see [new documentation link]. The old platform will be retired on [Date]."\n\nSupport team documentation:\n\nSupport staff need documentation that helps them identify which system a caller is on before diagnosing their issue. A triage guide for support staff is often the most urgent documentation project in a dual-system period.`, subcategory: null, difficulty: "Hard", domain: "telecom", tracks: ["Content Strategy"], companies: [], roundType: "content_strategy", whatInterviewerTests: "", commonMistakes: []},
    {q: "You are a content strategist at a fintech company. How do you create documentation that serves both first-time users and power users without creating two separate documentation sets?", a: `Serving first-time users and power users in a single documentation set requires a progressive disclosure architecture — where basic information is immediately accessible and advanced information is available but not forced on users who do not need it.\n\nThe challenge: first-time users need context and explanation that power users find patronizing. Power users need depth and technical detail that overwhelms first-time users. A documentation set that tries to serve both equally in the same content frustrates both.\n\nProgressive disclosure architecture:\n\nEntry-level articles cover the basic use case with the minimum information needed to accomplish the task. They are written for someone with no prior experience. They link to advanced articles for users who want more.\n\nAdvanced articles cover edge cases, configuration options, API access, automation, and integration scenarios. They assume familiarity with the basic use case and do not repeat foundational explanations.\n\nThe structure works because each user finds what they need without navigating content irrelevant to them.\n\nSpecific techniques:\n\nLayered content within articles: For some topics, I use expandable sections. The main article covers the common use case; "Advanced options" and "Technical details" sections are collapsed by default and expanded only by users who want that depth.\n\nAudience-tagged content: Some articles are explicitly labeled "For new users" or "For administrators." This makes self-selection easy.\n\nSearch optimization for different queries: First-time users search for "how to transfer money." Power users search for "transfer API rate limits." SEO-optimized titles and metadata ensure each user finds the relevant depth level.\n\nGetting started path: A curated onboarding path through the documentation for first-time users — not a separate documentation set, but a guided traversal of existing content in the right sequence.`, subcategory: null, difficulty: "Medium", domain: "fintech", tracks: ["Content Strategy"], companies: [], roundType: "content_strategy", whatInterviewerTests: "", commonMistakes: []},
    {q: "You are a documentation manager at a bank. You are asked to implement a peer review process for the documentation team. How do you design this?", a: `A peer review process for documentation improves content quality, builds team skill, and creates shared standards — but only if it is designed well. Poorly designed peer review wastes time, creates conflict, and produces inconsistent outcomes.\n\nDesign principles:\n\nDefine what peer review is for: Peer review is for content quality — accuracy, clarity, structure, and adherence to style standards. It is not for personal preference, stylistic opinions, or editorial decisions that are within the author's authority to make. Without this definition, peer review becomes a source of conflict as reviewers make changes the author did not agree to and did not need.\n\nSeparate peer review from technical accuracy review: Peer review by another writer evaluates the documentation quality. Technical accuracy review by a subject matter expert evaluates the factual correctness. These are different skills and should not be combined in one review stage.\n\nStructured review checklist: I create a checklist that guides reviewers to assess specific quality criteria: Is the audience clear? Does the title describe the content accurately? Are the steps correct and in the right sequence? Does the language meet the style guide standards? Are there any unexplained terms or acronyms? Is the content complete — are there any obvious gaps? A checklist produces more consistent, actionable feedback than an open review.\n\nReview scope definition: I define what is in scope for a peer review — content quality — and what is out of scope — substantive technical changes that require SME review, major structural changes that require manager approval. Reviewers who stay in scope produce useful feedback; those who go out of scope create confusion about authority.\n\nFeedback format: Reviewers provide feedback in two categories: must-fix (errors, factual issues, missing required elements) and suggestions (optional improvements the author can accept or decline). This distinction prevents the author from feeling that all feedback is mandatory.`, subcategory: null, difficulty: "Medium", domain: "banking", tracks: ["Content Strategy"], companies: [], roundType: "content_strategy", whatInterviewerTests: "", commonMistakes: []},
    {q: "You are a content strategist at an insurance company. The company is expanding its product line and wants to ensure new products have comprehensive documentation from day one. How do you build documentation into the product development process?", a: `Documentation that is ready on day one requires embedding technical writers in the product development process from the requirements stage, not the launch stage. Documentation that is produced after development is complete is always late, always based on incomplete information, and always produces a worse outcome than documentation developed in parallel with the product.\n\nHow to build documentation into the product development process:\n\nRequirements stage involvement:\n\nTechnical writers attend requirements reviews and use documentation planning as a quality tool. A requirement that cannot be documented clearly is often a requirement that is not well-defined. The documentation team's questions during requirements review — "who is the user?", "what are they trying to accomplish?", "what does success look like?" — improve the requirements as much as they inform the documentation plan.\n\nDesign review involvement:\n\nTechnical writers review design mockups and user flows with specific questions: what does the user need to know at this point in the flow? What happens if the user does not have the required information? Are there error states that need to be documented? These questions surface documentation requirements that might otherwise be discovered only after launch.\n\nContent requirements document:\n\nFor each new product, I produce a content requirements document alongside the product requirements document. It lists every piece of documentation needed — user guide, help articles, regulatory disclosure summary, sales agent reference guide — with the owner, timeline, and review requirements for each. This document is tracked in the project plan alongside technical deliverables.\n\nDocumentation acceptance criteria:\n\nI work with the product team to include documentation readiness in the definition of done for product launch. A product that is technically complete but has no user-facing documentation is not ready to launch. Making documentation a launch requirement prevents it from being deprioritized in the final weeks before release.`, subcategory: null, difficulty: "Hard", domain: "insurance", tracks: ["Content Strategy"], companies: [], roundType: "content_strategy", whatInterviewerTests: "", commonMistakes: []},
    {q: "You are a content strategist at a telecom company. How do you build and maintain a content partnership with the product team to ensure documentation stays current?", a: `A content partnership with the product team is the most important relationship a documentation team has, because the product team controls the changes that make documentation outdated and the information that makes documentation accurate. A poor partnership produces a documentation team that is always chasing changes it did not know about.\n\nBuilding the partnership:\n\nEmbed in product team rituals: I request to attend sprint reviews, product roadmap sessions, and design reviews — not as a passive observer but as a contributor who provides documentation perspective. A writer who attends these sessions stays informed about changes as they happen rather than discovering them after they ship.\n\nCreate a change notification system: I work with the product team to establish that product changes which affect the user interface, user flows, or product terms trigger a documentation notification. The product manager or designer who makes a change adds a documentation label in Jira or sends a message in a dedicated channel. This is a lightweight process that produces significant documentation currency improvements.\n\nMake documentation useful to the product team: Product teams prioritize relationships with teams that create value for them. I position documentation as something that benefits the product team — reducing support escalations to the product team, providing user research insights from help center search data, and making it easier to onboard new team members. When the product team sees documentation as serving their goals, they prioritize the relationship.\n\nMaintaining the partnership:\n\nRegular documentation health reviews with the product team: A monthly or quarterly review where the documentation team presents the quality metrics — search volume, article satisfaction ratings, support deflection rates — for the product team's features. This keeps documentation visible as a product quality metric and creates shared accountability for documentation currency.\n\nPost-launch documentation retrospectives: After each major product release, a brief retrospective with the product team on what the documentation process worked well and what could have been done earlier creates continuous improvement in the partnership process.`, subcategory: null, difficulty: "Medium", domain: "telecom", tracks: ["Content Strategy"], companies: [], roundType: "content_strategy", whatInterviewerTests: "", commonMistakes: []},
  ]
};

const filePath = path.join(__dirname, 'src/data/technicalWritingQuestions.js');
let fileContent = fs.readFileSync(filePath, 'utf-8');

let totalAdded = 0;

for (const [roundType, questions] of Object.entries(questionsToAppend)) {
  const pattern = `"${roundType}": [`;
  const startIndex = fileContent.indexOf(pattern, fileContent.indexOf('"Technical Writer"'));

  if (startIndex === -1) {
    console.error(`Could not find "${roundType}" array in Technical Writer`);
    continue;
  }

  const bracketStart = fileContent.indexOf('[', startIndex);
  let bracketCount = 0;
  let bracketEnd = bracketStart;

  for (let i = bracketStart; i < fileContent.length; i++) {
    if (fileContent[i] === '[') bracketCount++;
    if (fileContent[i] === ']') bracketCount--;
    if (bracketCount === 0) {
      bracketEnd = i;
      break;
    }
  }

  const questionStrings = questions.map(q => JSON.stringify(q, null, 6)).join(',\n    ');
  const beforeClose = fileContent.substring(0, bracketEnd);
  const afterClose = fileContent.substring(bracketEnd);

  const arrayContent = fileContent.substring(bracketStart + 1, bracketEnd).trim();
  const separator = arrayContent.length > 0 ? ',\n    ' : '\n    ';

  fileContent = beforeClose + separator + questionStrings + '\n    ' + afterClose;

  totalAdded += questions.length;
  console.log(`Added ${questions.length} ${roundType} questions`);
}

fs.writeFileSync(filePath, fileContent, 'utf-8');
console.log(`Total ${totalAdded} new questions added!`);
